SELECT 
FROM TBL_FINANCING_REPAYMENT
WHERE DELETE_FLAG = 0

    AND DRAWDOWN_ID = #{drawdownId}


    AND COMPANY_ID = #{companyId}


    AND REPAYMENT_STATUS = #{repaymentStatus}

ORDER BY PLAN_DATE ASC

SELECT FROM TBL_FINANCING_REPAYMENT WHERE DELETE_FLAG = 0
AND FINANCING_ID = #{financingId}
ORDER BY PLAN_DATE ASC
